import React, { useState } from 'react';
import TrafficLight from './TrafficLight';
import './ApproachCard.css';

function ApproachCard({
  approach,
  label,
  signal,
  traffic,
  inputHealth,
  phaseTimer,
  isActivePhase,
  mode,
  onManualSignal,
  onRequestPhase,
  decisionExplanation
}) {
  const [requestedDuration, setRequestedDuration] = useState(15);

  const getDensityColor = (density) => {
    switch (density) {
      case 'low': return '#4ade80';
      case 'medium': return '#fbbf24';
      case 'high': return '#f97316';
      case 'congested': return '#ef4444';
      default: return '#888';
    }
  };

  const getDensityLabel = (density) => {
    switch (density) {
      case 'low': return 'Low';
      case 'medium': return 'Medium';
      case 'high': return 'High';
      case 'congested': return 'Congested';
      default: return 'Unknown';
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'ok': return '#4ade80';
      case 'stale': return '#fbbf24';
      case 'degraded': return '#f97316';
      case 'disconnected': return '#ef4444';
      default: return '#888';
    }
  };

  const getSignalPhase = () => {
    if (isActivePhase && signal === 'green') {
      return `Phase Active (${approach === 'north' || approach === 'south' ? 'N/S' : 'E/W'})`;
    }
    if (signal === 'yellow') return 'Transitioning';
    return 'Stopped';
  };

  const formatWaitTime = (ms) => {
    if (!ms) return '0s';
    const s = Math.round(ms / 1000);
    if (s >= 60) return `${Math.floor(s / 60)}m ${s % 60}s`;
    return `${s}s`;
  };

  const formatPhaseTimer = (ms) => {
    if (!ms) return '--';
    const s = Math.round(ms / 1000);
    return `${s}s`;
  };

  const getPhaseForApproach = () => {
    return (approach === 'north' || approach === 'south') ? 'north-south' : 'east-west';
  };

  const handleSignalRequest = (targetSignal) => {
    if (mode === 'MANUAL') {
      onManualSignal(approach, targetSignal, requestedDuration * 1000);
    }
  };

  const handlePhaseRequest = () => {
    onRequestPhase(getPhaseForApproach());
  };

  return (
    <div className={`approach-card ${signal}`}>
      <div className="approach-header">
        <div className="approach-title">
          <span className="approach-direction">{label}</span>
          <div className="approach-badges">
            <span className={`phase-indicator ${isActivePhase ? 'active' : ''}`}>
              {isActivePhase ? 'Phase Active' : 'Waiting'}
            </span>
            <span className={`control-indicator control-${mode.toLowerCase()}`}>
              {mode}
            </span>
          </div>
        </div>
        <div className="input-status">
          <span className="input-item">
            <span className="input-dot" style={{ background: getStatusColor(inputHealth.camera) }} />
            Camera: {inputHealth.camera === 'ok' ? 'SIMULATED' : inputHealth.camera.toUpperCase()}
          </span>
          <span className="input-item">
            <span className="input-dot" style={{ background: getStatusColor(inputHealth.sensor) }} />
            Sensor: {inputHealth.sensor === 'ok' ? 'SIMULATED' : inputHealth.sensor.toUpperCase()}
          </span>
        </div>
      </div>

      <div className="approach-body">
        <div className="traffic-light-section">
          <TrafficLight
            signal={signal}
            approach={approach}
          />

          <div className="signal-info">
            <div className="signal-state">
              <span className={`signal-badge signal-${signal}`}>
                {signal.toUpperCase()}
              </span>
              <span className="signal-phase">{getSignalPhase()}</span>
            </div>

            {isActivePhase && phaseTimer > 0 && (
              <div className="phase-timer">
                <span className="timer-value">{formatPhaseTimer(phaseTimer)}</span>
                <span className="timer-label">remaining</span>
              </div>
            )}
          </div>
        </div>

        <div className="traffic-metrics">
          <div className="metrics-row">
            <div className="metric-item">
              <span className="metric-label">Vehicles</span>
              <span className="metric-value">{traffic.count}</span>
            </div>
            <div className="metric-item">
              <span className="metric-label">Density</span>
              <span className="metric-value" style={{ color: getDensityColor(traffic.density) }}>
                {getDensityLabel(traffic.density)}
              </span>
            </div>
            <div className="metric-item">
              <span className="metric-label">Queue</span>
              <span className="metric-value">{traffic.queueLength}</span>
            </div>
          </div>

          <div className="metrics-row">
            <div className="metric-item">
              <span className="metric-label">Wait</span>
              <span className="metric-value">{formatWaitTime(traffic.waitTime)}</span>
            </div>
            <div className="metric-item">
              <span className="metric-label">Moving</span>
              <span className="metric-value">{traffic.moving}</span>
            </div>
            <div className="metric-item">
              <span className="metric-label">Speed</span>
              <span className="metric-value">{traffic.speed} km/h</span>
            </div>
          </div>

          <div className="congestion-bar">
            <div className="congestion-label-row">
              <span>Congestion</span>
              <span style={{ color: getDensityColor(traffic.density) }}>
                {getDensityLabel(traffic.density)}
              </span>
            </div>
            <div className="congestion-track">
              <div
                className="congestion-fill"
                style={{
                  width: `${Math.min(100, (traffic.count / 20) * 100)}%`,
                  background: getDensityColor(traffic.density)
                }}
              />
            </div>
          </div>
        </div>
      </div>

      {decisionExplanation && isActivePhase && (
        <div className="decision-reason">
          <span className="reason-icon">ℹ</span>
          <span className="reason-text">{decisionExplanation}</span>
        </div>
      )}

      <div className="approach-controls">
        {mode === 'MANUAL' ? (
          <div className="manual-controls">
            <span className="controls-label">Signal Control</span>
            <div className="signal-buttons">
              <button
                className="signal-btn green-btn"
                onClick={() => handleSignalRequest('green')}
                disabled={signal === 'green'}
              >
                Green
              </button>
              <button
                className="signal-btn yellow-btn"
                onClick={() => handleSignalRequest('yellow')}
                disabled={signal === 'yellow' || signal === 'red'}
              >
                Yellow
              </button>
              <button
                className="signal-btn red-btn"
                onClick={() => handleSignalRequest('red')}
                disabled={signal === 'red'}
              >
                Red
              </button>
            </div>
            <div className="duration-control">
              <span>Green duration: {requestedDuration}s</span>
              <input
                type="range"
                min="5"
                max="30"
                value={requestedDuration}
                onChange={(e) => setRequestedDuration(parseInt(e.target.value))}
                className="duration-slider"
              />
            </div>
            <button
              className="phase-request-btn"
              onClick={handlePhaseRequest}
            >
              Request Phase
            </button>
          </div>
        ) : (
          <div className="ai-status-controls">
            <span className="ai-control-label">
              AI Control Active — Adaptive timing
            </span>
            {traffic.dataSource && (
              <span className="data-source-label">
                Data: {traffic.dataSource === 'camera' ? 'Camera (Simulated)' : traffic.dataSource}
              </span>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

export default ApproachCard;
